import{_ as t,H as i,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"09 | 性能测试的种类：如何快准狠地抓住一个测试的本质？","description":"","frontmatter":{},"headers":[{"level":2,"title":"性能测试的分类方式","slug":"性能测试的分类方式","link":"#性能测试的分类方式","children":[{"level":3,"title":"测试目的","slug":"测试目的","link":"#测试目的","children":[]},{"level":3,"title":"测试环境","slug":"测试环境","link":"#测试环境","children":[]},{"level":3,"title":"负载流量","slug":"负载流量","link":"#负载流量","children":[]},{"level":3,"title":"测试对象","slug":"测试对象","link":"#测试对象","children":[]},{"level":3,"title":"负载数据","slug":"负载数据","link":"#负载数据","children":[]},{"level":3,"title":"黑盒白盒","slug":"黑盒白盒","link":"#黑盒白盒","children":[]}]},{"level":2,"title":"性能测试的种类","slug":"性能测试的种类","link":"#性能测试的种类","children":[{"level":3,"title":"冒烟测试（Smoke Testing）","slug":"冒烟测试-smoke-testing","link":"#冒烟测试-smoke-testing","children":[]},{"level":3,"title":"耐力测试（Endurance Testing）和浸泡测试（Soak Testing）","slug":"耐力测试-endurance-testing-和浸泡测试-soak-testing","link":"#耐力测试-endurance-testing-和浸泡测试-soak-testing","children":[]},{"level":3,"title":"基准测试（Benchmark Testing）/性能回归测试（Performance Regression Testing）","slug":"基准测试-benchmark-testing-性能回归测试-performance-regression-testing","link":"#基准测试-benchmark-testing-性能回归测试-performance-regression-testing","children":[]},{"level":3,"title":"负载测试（Load Testing）","slug":"负载测试-load-testing","link":"#负载测试-load-testing","children":[]},{"level":3,"title":"断点测试（Breakpoint Testing）","slug":"断点测试-breakpoint-testing","link":"#断点测试-breakpoint-testing","children":[]},{"level":3,"title":"尖峰测试（Spike Testing）","slug":"尖峰测试-spike-testing","link":"#尖峰测试-spike-testing","children":[]},{"level":3,"title":"可扩展性测试（Scalability Testing）","slug":"可扩展性测试-scalability-testing","link":"#可扩展性测试-scalability-testing","children":[]},{"level":3,"title":"容量测试（Capacity Testing）","slug":"容量测试-capacity-testing","link":"#容量测试-capacity-testing","children":[]},{"level":3,"title":"瓶颈测试（Bottleneck Testing）","slug":"瓶颈测试-bottleneck-testing","link":"#瓶颈测试-bottleneck-testing","children":[]},{"level":3,"title":"压力测试（Stress Testing）","slug":"压力测试-stress-testing","link":"#压力测试-stress-testing","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"性能工程高手课/09-性能测试的种类：如何快准狠地抓住一个测试的本质？.md","filePath":"性能工程高手课/09-性能测试的种类：如何快准狠地抓住一个测试的本质？.md","lastUpdated":1779819865000}'),s={name:"性能工程高手课/09-性能测试的种类：如何快准狠地抓住一个测试的本质？.md"};function l(r,e,o,h,g,c){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_09-性能测试的种类-如何快准狠地抓住一个测试的本质" tabindex="-1">09 | 性能测试的种类：如何快准狠地抓住一个测试的本质？ <a class="header-anchor" href="#_09-性能测试的种类-如何快准狠地抓住一个测试的本质" aria-label="Permalink to &quot;09 | 性能测试的种类：如何快准狠地抓住一个测试的本质？&quot;">​</a></h1><p>你好，我是庄振运。</p><p>从这一讲开始我们讨论性能测试。性能测试是一种特殊的软件测试，它的目的是 <strong>确保软件应用程序在一定的负载流量下运行良好</strong>。性能测试是性能分析和性能优化的基础，它的目标是 <strong>发现和性能相关的各种问题和性能瓶颈，从而进一步去消除错误和性能瓶颈</strong>。</p><p>由于性能测试本身就有好多种类；加上各种测试之间的界限其实很模糊，这就造成了很多人理解上的混乱。</p><p>比如大家在工作讨论时，经常说做性能测试，但对于做什么样的“性能测试”，每个人有不同的看法，而且又经常表达不清。这就造成来交流不畅，甚至是误解，从而严重地影响了工作的速度。我见过很多次因为对性能测试定义和交代不清，造成了老板和员工之间/员工和员工之间的理解误差。</p><p>性能测试的种类颇多，各自有不同的测试目的、测试环境、负载等等；这里面最重要的是测试目的和负载的大小变化。我们这一讲就一起来分一下类。</p><h2 id="性能测试的分类方式" tabindex="-1">性能测试的分类方式 <a class="header-anchor" href="#性能测试的分类方式" aria-label="Permalink to &quot;性能测试的分类方式&quot;">​</a></h2><p>性能测试如何分类呢？我们需要从几个方面来看，包括测试目的、测试环境、负载流量、测试对象、负载数据、黑盒白盒等。</p><h3 id="测试目的" tabindex="-1">测试目的 <a class="header-anchor" href="#测试目的" aria-label="Permalink to &quot;测试目的&quot;">​</a></h3><p>测试目的是最重要的方面。大体上有几种目的：</p><ol><li>测量服务速度（Speed）：确定程序是否能够快速地响应用户的请求，这个服务速度一般包括延迟和吞吐率两个指标。速度通常是应用程序最重要的属性之一，因为运行缓慢的应用程序容易丢失用户。</li><li>测量可扩展性（Scalability）：确定应用程序是否可以在用户负载和客户流量增大情况下还能正常地运行。</li><li>测量稳定性（Stability）：确定在各种极端和恶劣环境下，应用程序是否能稳定运行。</li><li>测量性能瓶颈（Performance Bottleneck）：性能瓶颈是应用程序和系统中的最影响整体性能的因素。瓶颈是指某个资源不足而导致某些负载下的性能降低。一些常见的性能瓶颈是CPU、内存、网络、存储等。</li></ol><h3 id="测试环境" tabindex="-1">测试环境 <a class="header-anchor" href="#测试环境" aria-label="Permalink to &quot;测试环境&quot;">​</a></h3><p>性能测试的环境也有几种，主要是开发环境还是生产环境。开发环境里面更多的是简单的测试来发现一些明显问题，而生产环境测试一般是开发环境测试通过后才进行的。</p><h3 id="负载流量" tabindex="-1">负载流量 <a class="header-anchor" href="#负载流量" aria-label="Permalink to &quot;负载流量&quot;">​</a></h3><p>根据测试的负载大小来分：是小流量，正常流量，还是超大流量。除了大小，负载变化的速度也需要考虑。</p><h3 id="测试对象" tabindex="-1">测试对象 <a class="header-anchor" href="#测试对象" aria-label="Permalink to &quot;测试对象&quot;">​</a></h3><p>测试的对象可以是只针对一个代码功能，或是整个代码模块，亦或是整个系统。</p><h3 id="负载数据" tabindex="-1">负载数据 <a class="header-anchor" href="#负载数据" aria-label="Permalink to &quot;负载数据&quot;">​</a></h3><p>测试的负载数据可以是真正的生产环境中的请求和数据，比如终端客户的网站请求和上传数据，也可以是人工模拟出来的请求及数据。</p><h3 id="黑盒白盒" tabindex="-1">黑盒白盒 <a class="header-anchor" href="#黑盒白盒" aria-label="Permalink to &quot;黑盒白盒&quot;">​</a></h3><p>如果把被测试的对象当作一个整体，不关心它的内部工作机理，也就是把它当作一个黑盒子，那么这种测试就是黑盒测试。反之，如果你也关心它的内部构件和内部设计，就是把它当作白盒子来测试。</p><h2 id="性能测试的种类" tabindex="-1">性能测试的种类 <a class="header-anchor" href="#性能测试的种类" aria-label="Permalink to &quot;性能测试的种类&quot;">​</a></h2><p>我们现在看看你可能经常会提到的各种测试，包括负载测试、容量测试、压力测试、断点测试、瓶颈测试、尖峰测试、耐力测试、基准测试、可扩展性测试和冒烟测试这10种。我分别说说它们是什么特点，尽量用刚刚讲过的分类方式归归类，并且适当举例说明。</p><p>需要说明的是，业界对于不同的测试类别其实也是各说各道，没有特别统一而严格的定义。我也是尽我所能，根据我的经验和实践来帮你理一理。</p><p>因为性能测试的种类多，我尽量把它们按照某种方式归类一下，帮助你理解和记忆。大体上可以按照负载流量的大小分成三类：低流量、中等流量和高流量。这里的流量高低是相对于生产环境中的流量而言的。当然，它们的实际界限其实很模糊。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E9%AB%98%E6%89%8B%E8%AF%BE/images/178227/dea330b04f4c81c71ab727b579e23b0c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E9%AB%98%E6%89%8B%E8%AF%BE/images/178227/dea330b04f4c81c71ab727b579e23b0c.png" alt=""></a></p><h3 id="冒烟测试-smoke-testing" tabindex="-1">冒烟测试（Smoke Testing） <a class="header-anchor" href="#冒烟测试-smoke-testing" aria-label="Permalink to &quot;冒烟测试（Smoke Testing）&quot;">​</a></h3><p>冒烟测试是开发人员在开发环境里执行的简单测试，以确定新的程序代码不出故障。冒烟测试目的是确认系统和程序基本功能正常。冒烟测试的执行者往往就是开发人员，但有时也让运维人员参与。</p><h3 id="耐力测试-endurance-testing-和浸泡测试-soak-testing" tabindex="-1">耐力测试（Endurance Testing）和浸泡测试（Soak Testing） <a class="header-anchor" href="#耐力测试-endurance-testing-和浸泡测试-soak-testing" aria-label="Permalink to &quot;耐力测试（Endurance Testing）和浸泡测试（Soak Testing）&quot;">​</a></h3><p>耐力测试（或者耐久测试）有时也叫浸泡测试，是一种非功能性测试。耐力测试是长时间测试具有预期负载量的系统，以验证系统的行为是否正常。举一个例子，假设系统设计工作时间是3小时；我们可以对这一系统进行超过3小时的测试，比如持续6小时的耐力测试，以检查系统的耐久性。</p><p>执行耐力测试最常见的用例是暴露某些不易重现的问题，如内存问题、系统故障或其他随机问题。</p><p>这里的偏重点是 <strong>测试时间</strong>，因为有些程序和系统的问题只有在长期运行后才暴露出来。一个最明显的例子就是内存泄漏。一个程序或许短时间内运行正常，但是如果有内存泄漏，只要运行时间足够，就一定会暴露出这个问题。</p><h3 id="基准测试-benchmark-testing-性能回归测试-performance-regression-testing" tabindex="-1">基准测试（Benchmark Testing）/性能回归测试（Performance Regression Testing） <a class="header-anchor" href="#基准测试-benchmark-testing-性能回归测试-performance-regression-testing" aria-label="Permalink to &quot;基准测试（Benchmark Testing）/性能回归测试（Performance Regression Testing）&quot;">​</a></h3><p>基准测试或者性能回归测试是着重“前后”对比的测试。</p><p>这种测试往往是开发过程的一部分，一般不需要具体的性能要求。代码的演化过程中经常需要确保新的代码不会对整个模块或系统的性能产生任何不好的影响。最简单的方法是对代码修改前后进行基准测试，并比较前后的性能结果。执行基准测试的重点是 <strong>保证前后测试环境的一致</strong>，比如负载流量的特征和大小。</p><h3 id="负载测试-load-testing" tabindex="-1">负载测试（Load Testing） <a class="header-anchor" href="#负载测试-load-testing" aria-label="Permalink to &quot;负载测试（Load Testing）&quot;">​</a></h3><p>负载测试用于验证被测试系统或者程序是否可以处理预期的负载流量，并验证正常和峰值负载条件下的系统和程序行为。这里的负载可以是真正的客户请求，也可以是仿真的人工产生的负载。</p><p>我认为负载测试的定义有时太广泛和模糊，很多其他测试都可以看作是负载测试的一种，比如马上就要讲到的容量测试，其实就是一种负载测试。</p><h3 id="断点测试-breakpoint-testing" tabindex="-1">断点测试（Breakpoint Testing） <a class="header-anchor" href="#断点测试-breakpoint-testing" aria-label="Permalink to &quot;断点测试（Breakpoint Testing）&quot;">​</a></h3><p>断点测试类似于压力测试或者容量测试。这种测试的过程是随着时间的推移而增大流量负载，同时监视系统的预定故障条件。</p><p>断点测试也可以用来确定系统将达到其所需规范或服务水平协议的最大容量，并且自动采取措施来纠正或者缓解。比如云计算环境中，我们可以设置某种性能断点，用它们来驱动某种扩展和伸缩策略。</p><p>比如一种性能断点可以是根据用户的访问延迟。如果延迟性能测量的结果是已经超过预定的阈值，就自动进行系统容量调整，比如增加云计算的服务器。反之，系统容量也可以根据断点的规则来减少，以节省成本。如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E9%AB%98%E6%89%8B%E8%AF%BE/images/178227/019067e2d02744e7ad7d4ff754523fd6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E9%AB%98%E6%89%8B%E8%AF%BE/images/178227/019067e2d02744e7ad7d4ff754523fd6.png" alt=""></a></p><h3 id="尖峰测试-spike-testing" tabindex="-1">尖峰测试（Spike Testing） <a class="header-anchor" href="#尖峰测试-spike-testing" aria-label="Permalink to &quot;尖峰测试（Spike Testing）&quot;">​</a></h3><p>尖峰测试用于确定系统在负载（比如用户请求数）突然变化时的系统行为。这种测试是通过突然增加或减少由用户产生的负载来观察系统的行为。</p><p>测试的目标是确定性能在这样的场景下是否会受损，系统是否会失败，或者是否能够处理负载的显著变化。尖峰测试的核心是 <strong>负载变化的突然性</strong>，所以也算是一种压力测试。</p><h3 id="可扩展性测试-scalability-testing" tabindex="-1">可扩展性测试（Scalability Testing） <a class="header-anchor" href="#可扩展性测试-scalability-testing" aria-label="Permalink to &quot;可扩展性测试（Scalability Testing）&quot;">​</a></h3><p>可扩展性（或者叫可伸缩性）测试用于确定一个程序和系统的非功能性特征能不能在变化的环境里合理扩展。这里的环境变化包括系统环境的变化、负载量的大小、请求的多样性、数据量的大小等。</p><p>在系统环境变化时，同步的测量和观察各种性能指标，并进行数据的分析，从而确定在各种环境下被测试系统的可扩展性。如下图所示。</p><p>这个测试的主要目的是了解系统在什么样的环境中，以及什么样的变化会导致系统不能扩展。发现这些环境后，可以进一步有针对性的分析和加强。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E9%AB%98%E6%89%8B%E8%AF%BE/images/178227/aed41953ab37b10ffabab3b12c283012.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E9%AB%98%E6%89%8B%E8%AF%BE/images/178227/aed41953ab37b10ffabab3b12c283012.png" alt=""></a></p><h3 id="容量测试-capacity-testing" tabindex="-1">容量测试（Capacity Testing） <a class="header-anchor" href="#容量测试-capacity-testing" aria-label="Permalink to &quot;容量测试（Capacity Testing）&quot;">​</a></h3><p>容量测试（或者叫体积测试，Volume Testing）是用于确定一个单位容量能够支持的最大负载。比如一个程序运行在某种服务器上，我们有时需要知道每台服务器能够支持的最大负载（例如客户数），从而决定需要部署多少台服务器才能满足预定的总负载要求。</p><p>容量测试一般是会不断增大负载，并且不断地测量各种性能指标。在性能目标变得不可接受之前，系统和程序可以成功处理的负载大小，就是单位容量可以承担的负载。为了尽量让得到的结果匹配实际生产环境，采用的负载流量最好是真正的生产环境的请求和数据。</p><p>正常生产环境中的流量和数据或许不够大到让一台服务器超载，因此我们需要解决这个问题。很多公司的解决方案是把其他服务器上的请求重定向到某一台被测试服务器，从而让这台服务器适度超载。这种机制我后面会用一讲专门讨论。</p><p>容量测试是确保系统稳定的重要一环。只有进行彻底的容量测试，并有相对应问题的解决方案，才可以使我们能够避免将来出现潜在的超载问题，例如增加的用户数或增加的数据量。</p><p>如下图所示，容量测试至少包含三个部分：可调节的流量负载、性能的测量、可以接受的性能指标。这三个部分一起就可以决定单位容量（比如一台服务器）的最大负载容量。这个数据可以帮助我们做各种决策，包括预估系统能负担的总负载；或者根据预期负载来决定部署多少台服务器。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E9%AB%98%E6%89%8B%E8%AF%BE/images/178227/0da67807c884dace487cb8f950bed136.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E9%AB%98%E6%89%8B%E8%AF%BE/images/178227/0da67807c884dace487cb8f950bed136.png" alt=""></a></p><h3 id="瓶颈测试-bottleneck-testing" tabindex="-1">瓶颈测试（Bottleneck Testing） <a class="header-anchor" href="#瓶颈测试-bottleneck-testing" aria-label="Permalink to &quot;瓶颈测试（Bottleneck Testing）&quot;">​</a></h3><p>瓶颈测试其实可以看作一种特殊的压力测试。它的目的是找到被测试系统和程序的最制约的资源类型（比如CPU或者存储）。瓶颈测试并不局限于只找到最制约的一个瓶颈，它也可以同时找多个性能瓶颈。</p><p>找多个性能瓶颈的的意义主要有两点：</p><ol><li>如果最制约的瓶颈资源解决了，那么其他制约资源类型就自动会成为下一个瓶颈，所以需要未雨绸缪。</li><li>系统设计时可以考虑在几个资源之间做些平衡，比如用内存空间来换取CPU资源的使用。</li></ol><h3 id="压力测试-stress-testing" tabindex="-1">压力测试（Stress Testing） <a class="header-anchor" href="#压力测试-stress-testing" aria-label="Permalink to &quot;压力测试（Stress Testing）&quot;">​</a></h3><p>压力测试也是一种负载测试，不过它偏重的是在负载增加到超过系统设计预期后观察和验证系统的行为。当我们通过增加负载，对系统施压到超出设计期望的负载时，就能发现哪个模块或组件首先因超载而失败。这样我们就可以通过提升失败组件的性能来设计出更健壮、性能更优的系统。</p><p>相对于容量测试，压力测试的目的是为了暴露系统的问题，因此采用的负载不一定是真正的生产数据和客户请求。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这一讲重点讲了几种性能测试。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E9%AB%98%E6%89%8B%E8%AF%BE/images/178227/1c5e4102c3f2b31b2f95ce9ee9851673.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E9%AB%98%E6%89%8B%E8%AF%BE/images/178227/1c5e4102c3f2b31b2f95ce9ee9851673.png" alt=""></a></p><p>在工作中和别人交流时，你一定还会听到各种不同叫法的性能测试。我从业多年的总体感觉就是，性能测试的种类太多，甚至对某一种测试怎么进行也众口纷纭。给人的感觉，就像古诗里面所说的，“乱花渐欲迷人眼”。</p><p>虽然各种性能测试叫法不一，但万变不离其宗，你只要主要抓住几点就行，比如分类的方式，流量的大小和测试的目的。</p><p>希望通过本讲的讨论，你能对不同的性能测试之间的区别更清楚一些了，以后工作交流和阅读文献时能搞清楚它们是什么种类的测试，从而对症下药，做好测试规划和合理的分析。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ul><li>今天讲了这么多种测试，你平时用过几种？</li><li>对于没有用过的测试种类，你清楚了解它们的使用场景吗？</li><li>如果有的测试种类看起来还挺有用但自己没有试过，尝试着设计一个，并在工作中表现一下，把这种测试和其他已经有的测试种类的区别好好分析一下，让同事们和领导知道你才是性能测试专家！</li></ul><p>欢迎你在留言区分享自己的思考，与我和其他同学一起讨论，也欢迎你把文章分享给自己的朋友。</p>',74)])])}const b=t(s,[["render",l]]);export{d as __pageData,b as default};
